content.content:
1	/* The hero stage. Broken steps drift in on the left, a white beam strikes a dark
2	   glass prism, and the spectrum fans out to the proof on the right.
3	   Canvas 2D, no library, DPR aware. It pauses off screen, in a hidden tab, and on
4	   request, and it draws one still frame under prefers-reduced-motion.
5	   The scene is decorative. The same facts live as text in the hero markup.
6	   API: window.FRPrism.mode("test"|"audit") */
7	(function(){
8	"use strict";
9	var st=document.getElementById("hero"),cv=document.getElementById("pz");
10	if(!st||!cv||!cv.getContext)return;
11	var c=cv.getContext("2d");if(!c)return;
12	var inL=document.getElementById("stIn"),outL=document.getElementById("stOut"),sky=document.getElementById("stSky"),pz=document.getElementById("stPause");
13	var chips=[].slice.call(inL.children),labs=[].slice.call(outL.children);
14	var MQ=matchMedia("(max-width:899px)"),RMQ=matchMedia("(prefers-reduced-motion:reduce)");
15	
16	/* every line below comes from a real run or audit in this repo (docs/runs, docs/audits, data/prs.json) */
17	var POOL={
18	 test:["No such option: --years","entire: command not found","Migration guide link: 404","Python version never stated","No module named 'typer'","curl: command not found","Docs say 0.9.0, not 0.9.58","KeyError: 'NEATLOGS_API_KEY'"],
19	 audit:["Flags page: 453 days old","29 code changes since edit","72 features with no docs","Infer-configs: 709 days old","15 stale of 1,405 pages","AccuKnox: 87 stale pages","Hard-deletes: 631 days old","AccuKnox page: 1,100 days old"]
20	};
21	/* spectrum, top to bottom. sRGB of oklch(65% .23 28), (78% .17 62), (90% .18 100), (76% .2 150), (68% .16 245), (58% .2 290) */
22	var BAND=[[255,72,66],[255,158,36],[255,222,60],[62,214,110],[64,166,255],[146,108,255]];
23	var WARM={test:[255,118,100],audit:[255,184,80]};
24	
25	var W=0,H=0,dpr=1,mob=false,G=null,lanes=[],parts=[],pulses=[],raf=0,vis=true,paused=false,still=RMQ.matches;
26	var t0=0,last=0,now=0,spawnAt=0,ks=0,rs=0,mode="test",mk=0,surge=0;
27	var ptr={x:0,y:0,tx:0,ty:0};
28	var off=document.createElement("canvas"),o=off.getContext("2d"),off2=document.createElement("canvas"),o2=off2.getContext("2d"),off3=document.createElement("canvas"),o3=off3.getContext("2d");
29	
30	function cl(v,a,b){return v<a?a:v>b?b:v}
31	function ease(k){k=cl(k,0,1);return 1-Math.pow(1-k,4)}
32	function lerp(a,b,k){return a+(b-a)*k}
33	function mix(p,q,k){return[Math.round(lerp(p[0],q[0],k)),Math.round(lerp(p[1],q[1],k)),Math.round(lerp(p[2],q[2],k))]}
34	function rgba(a,al){return"rgba("+a[0]+","+a[1]+","+a[2]+","+al+")"}
35	function quad(a,b,d,u){var v=1-u;return{x:v*v*a.x+2*v*u*b.x+u*u*d.x,y:v*v*a.y+2*v*u*b.y+u*u*d.y}}
36	function cub(a,b,d,e,u){var v=1-u,A=v*v*v,B=3*v*v*u,C=3*v*u*u,D=u*u*u;return{x:A*a.x+B*b.x+C*d.x+D*e.x,y:A*a.y+B*b.y+C*d.y+D*e.y}}
37	function rel(r,R){return{l:r.left-R.left,t:r.top-R.top,r:r.right-R.left,b:r.bottom-R.top}}
38	
39	/* ---------- layout: measure the stage and place the prism, lanes and labels ---------- */
40	function layout(){
41	 mob=MQ.matches;
42	 var R=cv.getBoundingClientRect();W=R.width;H=R.height;if(W<2||H<2)return;
43	 var px=W*H,cap=mob?2:2.2e6;
44	 dpr=Math.min(window.devicePixelRatio||1,2);if(px*dpr*dpr>cap*2)dpr=Math.max(1,Math.sqrt(cap*2/px));
45	 cv.width=Math.round(W*dpr);cv.height=Math.round(H*dpr);
46	 off.width=Math.max(2,Math.ceil(W/2));off.height=Math.max(2,Math.ceil(H/2));
47	 off2.width=Math.max(2,Math.ceil(W/6));off2.height=Math.max(2,Math.ceil(H/6));
48	 off3.width=Math.max(2,Math.ceil(W/16));off3.height=Math.max(2,Math.ceil(H/16));
49	 G={};
50	 if(mob){
51	  var hm=Math.min(H*.66,W*.52);G.h=hm;G.w=hm*1.1547;G.cx=W*.46;G.ay=(H-hm)*.5;
52	  G.fx=W-2;G.top=12;G.bot=H-12;G.ly=[];for(var m=0;m<6;m++)G.ly.push(lerp(H*.2,H*.86,m/5));
53	  G.y0=null;lanes=[];
54	  chips.concat(labs).forEach(function(li){li.classList.remove("off");["transform","opacity","left","top"].forEach(function(p){li.style.removeProperty(p)})});
55	 }else{
56	  var S=st.getBoundingClientRect(),h1=rel(st.querySelector("h1").getBoundingClientRect(),S),fm=rel(document.getElementById("f").getBoundingClientRect(),S),hn=rel(document.getElementById("hint").getBoundingClientRect(),S),ch=rel(document.getElementById("chips").getBoundingClientRect(),S);
57	  /* vertical rhythm: a clear gap under the helper text, then the prism, then a margin above
58	     the horizon curve. A short stage shrinks the prism instead of letting it climb. */
59	  var hz=document.querySelector(".hz"),hzT=hz?rel(hz.getBoundingClientRect(),S).t:H-62;
60	  var gap=cl(H*.075,56,80),top=hn.b+gap,bot=hzT-cl(H*.05,36,56),sh=Math.max(120,bot-top);
61	  var h=cl(sh,120,Math.min(360,W*.26));G.h=h;G.w=h*1.1547;G.cx=W/2;G.ay=top+(sh-h)*.45;G.top=top;G.bot=bot;
62	  var lw=0,lh=0;labs.forEach(function(li){lw=Math.max(lw,li.offsetWidth);lh=Math.max(lh,li.offsetHeight)});
63	  G.fx=Math.min(Math.max(G.cx+G.w*.5+70,W*.75),W-lw-34);
64	  /* labels: a column on the right. Start beside the input when that column is clear of it,
65	     else below the input when it clears the example chips and the hint, else under the hint */
66	  var lx=G.fx+12,y0=lx>fm.r+24||lx>Math.max(ch.r,hn.r)+24?fm.b+30:hn.b+30;
67	  var y1=bot-lh/2,tight=(y1-y0)/5<46;
68	  outL.classList.toggle("tight",tight);
69	  if(tight){lh=0;labs.forEach(function(li){lh=Math.max(lh,li.offsetHeight)});y1=bot-lh/2}
70	  var sp=cl((y1-y0)/5,tight?26:46,92),mid=Math.min((y0+y1)/2,y1-sp*2.5);
71	  G.ly=[];for(var i=0;i<6;i++)G.ly.push(mid+(i-2.5)*sp);G.sp=sp;
72	  labs.forEach(function(li,k){li.style.left=lx+"px";li.style.top=(G.ly[k]-li.offsetHeight/2)+"px"});
73	  G.cl=Math.min(h1.l,fm.l);G.ct=h1.t;G.cb=hn.b;
74	 }
75	 geo(0,0);
76	 /* anchor the backdrop light to the scene: the halo on the prism, the bleed where the rays land */
77	 if(sky){var so=rel(cv.getBoundingClientRect(),st.getBoundingClientRect());
78	  [["--pcx",so.l+G.cx],["--pcy",so.t+G.ay+G.h*.62],["--pby",so.t+G.ay+G.h],["--pfx",so.l+(mob?W*.86:G.fx)]].forEach(function(v){sky.style.setProperty(v[0],Math.round(v[1])+"px")})}
79	 cone();
80	 /* chip lanes: start in the left column, curve down into the beam */
81	 lanes=[];
82	 if(!mob){
83	  /* with a wide left column the lanes start beside the headline. Their threads fall in a
84	     gutter between the chips and the text, then merge into the beam farther along. */
85	  /* the calmer composition won: chips live in the band below the text, beside the beam.
86	     Set wideL to true to let them climb beside the headline on very wide screens. */
87	  /* lane centers stay one chip height plus a margin apart. A short band shows fewer chips. */
88	  var chH=chips[0].offsetHeight||31,minSp=chH+12;
89	  var wideL=false,yA=wideL?Math.max(G.ct+26,120):G.cb+cl((G.top-G.cb)*.7,36,52)+chH/2,yB=G.bot-chH/2,xs=[0,38,12,52,22],wi=0;
90	  var bc0=beamY(Math.max(16,W*.034)+150),gp0=bc0-28>yA&&bc0+28<yB?56:0;
91	  var n=Math.max(1,Math.min(chips.length,Math.floor((yB-yA-gp0)/minSp)+1));
92	  chips.forEach(function(li,j){li.classList.toggle("off",j>=n)});
93	  G.gut=wideL?G.cl-82:1e4;
94	  for(var j=0;j<n;j++){
95	   /* spread the lanes evenly, skipping a band around the beam so no chip sits on it */
96	   var sx=Math.max(16,W*.034)+xs[j%xs.length],bc=beamY(sx+130),hasGap=bc-28>yA&&bc+28<yB,span=(yB-yA)-(hasGap?56:0);
97	   var sy=yA+span*(n>1?j/(n-1):.5);if(hasGap&&sy>bc-28)sy+=56;
98	   var wide=wideL&&sy<G.cb+6;
99	   var bx=lerp(Math.min(G.Pin.x-80,W*.41),Math.min(G.Pin.x-120,W*.29),n>1?j/(n-1):.5),by=beamY(bx);
100	   lanes.push({S:{x:sx,y:sy},C:{x:sx+(bx-sx)*.62,y:sy},B:{x:bx,y:by},ph:j/n+.07*Math.sin(j*2.3),w:0,q:-1,wide:wide,drop:wide?G.cl-34-14*(wi++):0});
101	  }
102	  chips.forEach(function(li,j){fit(j)});
103	 }
104	 if(still||paused||!raf)frame(now||performance.now());
105	}
106	function beamY(x){return lerp(G.y0,G.Pin.y,x/G.Pin.x)}
107	/* the haze the beam lights on its way in: drawn once per layout at 1/12 scale, so the upscale
108	   blurs it for free. Each frame only blits the band around the beam. */
109	var vc=document.createElement("canvas"),v=vc.getContext("2d"),VB=null;
110	function cone(){
111	 var s=1/12,P=G.Pin,y0=G.y0,a=G.h*.3,b=G.h*.2,x1=P.x+G.w*.05;
112	 vc.width=Math.max(2,Math.ceil(W*s));vc.height=Math.max(2,Math.ceil(H*s));
113	 v.setTransform(s,0,0,s,0,0);
114	 var g=v.createLinearGradient(0,0,x1,0);g.addColorStop(0,"rgba(214,222,255,0)");g.addColorStop(.5,"rgba(214,222,255,.28)");g.addColorStop(.92,"rgba(236,240,255,.75)");g.addColorStop(1,"rgba(236,240,255,0)");
115	 v.fillStyle=g;v.beginPath();v.moveTo(0,y0-a);v.lineTo(P.x,P.y-b);v.lineTo(x1,P.y);v.lineTo(P.x,P.y+b);v.lineTo(0,y0+a);v.closePath();v.fill();
116	 var t=Math.max(0,Math.min(y0,P.y)-a-24),bt=Math.min(H,Math.max(y0,P.y)+a+24);VB={x:0,y:t,w:Math.min(W,x1+24),h:bt-t,s:s};
117	}
118	function drawCone(k,fl){
119	 if(!VB||k<=0)return;var B=VB;
120	 c.save();c.globalCompositeOperation="lighter";c.globalAlpha=.16*k*fl;
121	 c.drawImage(vc,B.x*B.s,B.y*B.s,B.w*B.s,B.h*B.s,B.x,B.y,B.w,B.h);c.restore();
122	}
123	/* prism geometry under the current tilt */
124	function geo(th,dy){
125	 var h=G.h,w=G.w,cx=G.cx,ay=G.ay+dy,gy=ay+h*2/3,cs=Math.cos(th),sn=Math.sin(th);
126	 function rot(x,y){var X=x-cx,Y=y-gy;return{x:cx+X*cs-Y*sn,y:gy+X*sn+Y*cs}}
127	 G.A=rot(cx,ay);G.L=rot(cx-w/2,ay+h);G.R=rot(cx+w/2,ay+h);
128	 G.Pin={x:lerp(G.A.x,G.L.x,.56),y:lerp(G.A.y,G.L.y,.56)};
129	 G.Pout={x:lerp(G.A.x,G.R.x,.6),y:lerp(G.A.y,G.R.y,.6)};
130	 if(G.y0===undefined||G.y0===null||!G.fixY)G.y0=G.Pin.y+G.Pin.x*.085;
131	 G.fixY=true;
132	}
133	/* the chip under lane j: measure its width once per text */
134	function fit(j){var li=chips[j],L=lanes[j];if(!L)return;L.w=li.offsetWidth;
135	 var lim=Math.min(G.gut,L.B.x-60),dx=lim-L.w-L.S.x,D=Math.max(1,L.B.x-L.S.x);
136	 L.um=cl(dx/(1.24*D),.02,.26)}
137	
138	/* ---------- chips: a slow conveyor of real failures ---------- */
139	var ptrQ={test:0,audit:0},shown={};
140	function nextText(){var P=POOL[mode],n=P.length,i=0;while(i<n){var s=P[ptrQ[mode]%n];ptrQ[mode]++;if(!shown[s])return s;i++}return P[ptrQ[mode]++%n]}
141	function setChip(j,s){var sp=chips[j].firstChild;if(sp.textContent!==s){delete shown[sp.textContent];sp.textContent=s;shown[s]=1;fit(j)}}
142	var CT=17000,swapT=-1e9;
143	function chipK(L,t){var cy=t/CT+L.ph,q=Math.floor(cy),k=cy-q;return{q:q,k:k}}
144	function chipsFrame(t){
145	 if(mob)return;
146	 var fade=still?1:cl((t-swapT)/420,0,1),intro=still?1:ease((t-t0-500)/900);
147	 lanes.forEach(function(L,j){
148	  var s=chipK(L,still?0:t),li=chips[j];
149	  if(s.q!==L.q){L.q=s.q;setChip(j,nextText())}
150	  var k=still?.32:s.k,u=L.um*k,p=quad(L.S,L.C,L.B,u);
151	  var al=still?1:Math.min(cl(k/.1,0,1),cl((1-k)/.2,0,1));
152	  al*=intro*(fade<1?(fade<.5?1-fade*2:fade*2-1):1);
153	  L.p=p;L.al=al;
154	  li.style.transform="translate3d("+(p.x+ptr.x*5).toFixed(1)+"px,"+(p.y-li.offsetHeight/2+ptr.y*4).toFixed(1)+"px,0)";
155	  li.style.opacity=al.toFixed(3);
156	 });
157	}
158	function swapChips(){
159	 /* fade out, change the pool, fade back in. Texts change at the fade midpoint. */
160	 swapT=now;var done=false;
161	 if(mob){inL.classList.add("swap")}
162	 setTimeout(function(){if(done)return;done=true;shown={};
163	  if(mob){ptrQ[mode]=0;chips.forEach(function(li,j){setChip(j,POOL[mode][j%POOL[mode].length])});inL.classList.remove("swap")}
164	  else lanes.forEach(function(L,j){L.q=chipK(L,now).q;setChip(j,nextText())});
165	  if(still||paused)frame(now)},210);
166	}
167	
168	/* ---------- drawing ---------- */
169	function drawFan(t,fanK,shift){
170	 var P=G.Pout,fx=lerp(P.x,G.fx,fanK),half=(mob?(G.ly[1]-G.ly[0]):G.sp)*.52;
171	 o.setTransform(1,0,0,1,0,0);o.clearRect(0,0,off.width,off.height);o.globalCompositeOperation="lighter";
172	 var s=.5,bands=[];
173	 for(var i=0;i<6;i++){
174	  var wob=still?0:Math.sin(t/1500+i*1.3)*H*.006+Math.sin(t/910+i*2.1)*H*.003;
175	  var yy=lerp(P.y,G.ly[i]+shift+wob,fanK),y0=P.y+(i-2.5)*1.6;
176	  bands.push([y0,yy]);
177	  var g=o.createLinearGradient(P.x*s,0,fx*s,0),col=BAND[i];
178	  g.addColorStop(0,rgba(col,.0));g.addColorStop(.06,rgba(col,.75));g.addColorStop(.6,rgba(col,.85));g.addColorStop(1,rgba(col,0));
179	  o.fillStyle=g;o.beginPath();o.moveTo(P.x*s,(y0-1.4)*s);o.lineTo(fx*s,(yy-half)*s);o.lineTo(fx*s,(yy+half)*s);o.lineTo(P.x*s,(y0+1.4)*s);o.closePath();o.fill();
180	 }
181	 o2.clearRect(0,0,off2.width,off2.height);o2.drawImage(off,0,0,off2.width,off2.height);
182	 o3.clearRect(0,0,off3.width,off3.height);o3.drawImage(off2,0,0,off3.width,off3.height);
183	 c.save();c.globalCompositeOperation="lighter";c.imageSmoothingEnabled=true;
184	 c.globalAlpha=.42;c.drawImage(off,0,0,W,H);
185	 c.globalAlpha=.85;c.drawImage(off2,0,0,W,H);
186	 c.globalAlpha=.75*(1+surge*.5);c.drawImage(off3,0,0,W,H);
187	 c.globalAlpha=1;
188	 /* crisp spines so each band reads as a ray */
189	 for(var j=0;j<6;j++){var lg=c.createLinearGradient(P.x,0,fx,0),cj=BAND[j];lg.addColorStop(0,rgba(cj,.0));lg.addColorStop(.12,rgba(cj,.7));lg.addColorStop(1,rgba(cj,0));
190	  c.strokeStyle=lg;c.lineWidth=1;c.beginPath();c.moveTo(P.x,bands[j][0]);c.lineTo(fx,bands[j][1]);c.stroke()}
191	 /* soft haze where the rays land */
192	 if(fanK>.6){var hk=(fanK-.6)/.4;for(var q=0;q<6;q++){var hy=G.ly[q]+shift,hx=G.fx-6,r=mob?40:Math.min(110,G.sp*1.3),hg=c.createRadialGradient(hx,hy,0,hx,hy,r);
193	  hg.addColorStop(0,rgba(BAND[q],.26*hk));hg.addColorStop(1,rgba(BAND[q],0));c.fillStyle=hg;c.fillRect(hx-r,hy-r,2*r,2*r)}}
194	 c.restore();
195	}
196	function drawBeam(t,k){
197	 var P=G.Pin,y0=G.y0,ex=lerp(0,P.x,k),ey=lerp(y0,P.y,k),fl=still?1:.9+.1*Math.sin(t/1700)+.03*Math.sin(t/430);
198	 fl*=1+surge*.35;
199	 var tint=mix([238,242,255],[244,232,255],mk);
200	 c.save();c.globalCompositeOperation="lighter";c.lineCap="round";
201	 var g=c.createLinearGradient(0,0,P.x,0);g.addColorStop(0,rgba(tint,0));g.addColorStop(.5,rgba(tint,.55*fl));g.addColorStop(1,rgba(tint,Math.min(1,fl)));
202	 c.strokeStyle=g;
203	 [[16,.06],[7,.14],[2.6,.75],[1.2,1]].forEach(function(l){c.globalAlpha=l[1];c.lineWidth=l[0];c.beginPath();c.moveTo(0,y0);c.lineTo(ex,ey);c.stroke()});
204	 c.restore();
205	}
206	function drawFunnels(){
207	 if(mob)return;
208	 c.save();c.lineWidth=1;var warm=mix(WARM.test,WARM.audit,mk);
209	 lanes.forEach(function(L){L.B.y=beamY(L.B.x);if(!L.p||L.al<.02)return;
210	  /* leave the chip level, then merge into the beam along its own direction */
211	  var a={x:L.p.x+L.w+8,y:L.p.y},dx=L.B.x-a.x,cx2=L.B.x-dx*.45,c2={x:cx2,y:beamY(cx2)};
212	  /* lanes beside the headline drop first, so they stay clear of the text column */
213	  var c1=L.wide?{x:L.drop,y:lerp(a.y,L.B.y,.62)}:{x:a.x+dx*.5,y:a.y};
214	  var g=c.createLinearGradient(a.x,a.y,L.B.x,L.B.y);g.addColorStop(0,rgba(warm,0));g.addColorStop(.2,rgba(warm,.3*L.al));g.addColorStop(1,"rgba(255,255,255,"+(.3*L.al)+")");
215	  c.strokeStyle=g;c.beginPath();c.moveTo(a.x,a.y);c.bezierCurveTo(c1.x,c1.y,c2.x,c2.y,L.B.x,L.B.y);c.stroke();L.a=a;L.c1=c1;L.c2=c2});
216	 c.restore();
217	}
