/* the three angles. Hover or focus opens one: its ray lights, the others step back, and one more
   line says where it leads. On a touch screen the first tap opens it and the second follows it. */
(function(){
 var h=$("hero"),G=[].slice.call(document.querySelectorAll("#stOut .grp")),hot=null,touch=false,was=false;
 function set(g){
  if(hot===g)return;
  if(hot)hot.classList.remove("hot");
  hot=g;
  if(g){g.classList.add("hot");h.setAttribute("data-focus",g.getAttribute("data-g"))}else h.removeAttribute("data-focus");
 }
 G.forEach(function(g){
  g.addEventListener("pointerenter",function(e){if(e.pointerType==="mouse")set(g)});
  g.addEventListener("pointerleave",function(e){if(e.pointerType==="mouse"&&!g.contains(document.activeElement))set(null)});
  g.addEventListener("pointerdown",function(e){touch=e.pointerType!=="mouse";was=hot===g});
  g.addEventListener("focusin",function(){set(g)});
  g.addEventListener("focusout",function(e){if(!g.contains(e.relatedTarget)&&!g.matches(":hover"))set(null)});
  g.addEventListener("click",function(e){if(touch&&!was){e.preventDefault();set(g)}touch=false});
 });
 document.addEventListener("pointerdown",function(e){if(hot&&!hot.contains(e.target))set(null)});
 document.addEventListener("keydown",function(e){if(e.key==="Escape"&&hot){var a=document.activeElement;set(null);if(a&&hot===null&&a.blur)a.blur()}});
 /* if the scene script never runs, show the angles as a still layout */
 setTimeout(function(){if(!h.classList.contains("live"))h.classList.add("flat")},2500);
})();
/* arriving at #hero from another page: put the cursor in the box */

