    rep.push({ size: s, ...m });
    if (w < 900) await p.screenshot({ path: `${out}/${tag}-${s}.png`, fullPage: true, clip: { x: 0, y: 0, width: w, height: Math.min(m.H + 40, 1700) } });
    else await p.screenshot({ path: `${out}/${tag}-${s}.png` });
    await ctx.close();
  }
  await b.close();
  for (const r of rep) console.log(JSON.stringify(r));
})();

