const [url, size, expr, shot, acts] = process.argv.slice(2);
(async () => {
  const [w, h] = size.split('x').map(Number);
  const b = await chromium.launch({ channel: 'msedge', headless: true });
  const p = await (await b.newContext({ viewport: { width: w, height: h } })).newPage();
  const errs = []; p.on('pageerror', e => errs.push(e.message)); p.on('console', m => { if (m.type() === 'error') errs.push(m.text()) });
  await p.route('**/assets/prism.js', async r => {
    const res = await r.fetch(); let t = await res.text();
    t = t.replace('window.FRPrism={', 'window.__G=function(){return G};window.FRPrism={');
    r.fulfill({ response: res, body: t, headers: { ...res.headers(), 'content-type': 'application/javascript' } });
  });
  await p.goto(url, { waitUntil: 'load' }); await p.mouse.move(-10, -10); await p.waitForTimeout(3200);
  for (const a of JSON.parse(acts || '[]')) {
    if (a.hover) await p.hover(a.hover);
    if (a.focus) await p.focus(a.focus);
    if (a.key) await p.keyboard.press(a.key);
    if (a.click) await p.click(a.click);
