// Touch taps, reduced motion, no-JS, keyboard order and frame cost.
const { chromium } = require('D:/Atharva/video-studio/node_modules/playwright-core');
const [out, url, tag = 's', only = 'all'] = process.argv.slice(2);
const want = k => only === 'all' || only.split(',').includes(k);
const inject = async p => p.route('**/assets/prism.js', async r => {
  const res = await r.fetch(); let t = await res.text();
  t = t.replace('function loop(t){', 'window.__ft=[];function loop(t){var __a=performance.now();').replace('frame(t);raf=requestAnimationFrame(loop);', 'frame(t);window.__ft.push([performance.now()-__a,t]);raf=requestAnimationFrame(loop);');
  r.fulfill({ response: res, body: t, headers: { ...res.headers(), 'content-type': 'application/javascript' } });
});
(async () => {
  const b = await chromium.launch({ channel: 'msedge', headless: true, args: ['--enable-gpu-rasterization', '--ignore-gpu-blocklist'] });
  if (want('touch')) {
    const ctx = await b.newContext({ viewport: { width: 375, height: 812 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
    const p = await ctx.newPage(); await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(2000);
    const box = await p.locator('#stOut .g1').boundingBox();
    await p.evaluate(y => scrollTo(0, y - 200), box.y);
    await p.waitForTimeout(300);
    const b2 = await p.locator('#stOut .g1').boundingBox();
    await p.touchscreen.tap(b2.x + 60, b2.y + 12); await p.waitForTimeout(700);
    const s1 = await p.evaluate(() => [location.hash, document.querySelector('#stOut .g1').className, document.getElementById('hero').dataset.focus]);
    await p.screenshot({ path: `${out}/${tag}-tap1-375.png` });
    const b3 = await p.locator('#stOut .g1').boundingBox();
    await p.touchscreen.tap(b3.x + 60, b3.y + 12); await p.waitForTimeout(1200);
    const s2 = await p.evaluate(() => [location.hash, Math.round(document.getElementById('receipt').getBoundingClientRect().top)]);
    console.log('touch tap 1', JSON.stringify(s1), 'tap 2', JSON.stringify(s2));
    await ctx.close();
  }
  if (want('kbd')) {
    const p = await (await b.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
    await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(2500);
    await p.focus('#u'); const seq = [];
    for (let i = 0; i < 9; i++) { await p.keyboard.press('Tab'); seq.push(await p.evaluate(() => { const a = document.activeElement; return (a.id || a.className || a.tagName) + ':' + (a.textContent || '').trim().slice(0, 24) + '|' + (document.getElementById('hero').dataset.focus || '-') })) }
    console.log('tab order', seq.join(' > '));
    await p.keyboard.press('Escape'); await p.waitForTimeout(300);
    console.log('after Escape focus attr', await p.evaluate(() => document.getElementById('hero').dataset.focus || 'none'));
    await p.context().close();
  }
  if (want('click')) {
    const p = await (await b.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
    await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(2500);
    const bx = await p.locator('#stOut .g2 .gt').boundingBox();
    await p.mouse.move(bx.x + 20, bx.y + 8); await p.waitForTimeout(500); await p.mouse.down(); await p.mouse.up(); await p.waitForTimeout(1500);
    console.log('click g2 ->', await p.evaluate(() => [location.hash, Math.round(document.getElementById('audit').getBoundingClientRect().top)]));
    await p.context().close();
  }
  if (want('reduced')) {
    const p = await (await b.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: 'reduce' })).newPage();
    await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(1500);
